private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        return null;
    }
    TreeNode<T> leftChild = node.left;
    if (leftChild == null) {
        return node;
    }

    // Preserve the original parent before mutating the pointers
    TreeNode<T> originalParent = node.parent;
    TreeNode<T> transferred = leftChild.right;

    // Perform the rotation
    leftChild.right = node;
    node.parent = leftChild;

    node.left = transferred;
    if (transferred != null) {
        transferred.parent = node;
    }

    // Reattach the rotated subtree to the original parent
    leftChild.parent = originalParent;
    if (originalParent != null) {
        if (originalParent.left == node) {
            originalParent.left = leftChild;
        } else if (originalParent.right == node) {
            originalParent.right = leftChild;
        }
    }

    return leftChild;
}

