    try{
        if(headerPart==null)return -1;
        int len=headerPart.length();
        if(end< -1 || end>=len-1)return -1;
        int i=end+1;
        while(i<len-1){
            if(headerPart.charAt(i)=='\r' && headerPart.charAt(i+1)=='\n'){
                return i+1; // index of '\n' in the \r\n sequence
            }
            i++;
        }
        return -1;
    }catch(Exception e){
        return -1;
    }
}

