public static <V,E> IsomorphicGraphMapping<V,E> function ( final Graph<V,E> graph ) { 
    if (graph == null) { 
        throw new IllegalArgumentException("Graph must not be null"); 
    } 
    try { 
        Map<V,V> vertexMap = new java.util.HashMap<>(); 
        for (V v : graph.vertexSet()) { 
            vertexMap.put(v, v); 
        } 
        Map<E,E> edgeMap = new java.util.HashMap<>(); 
        for (E e : graph.edgeSet()) { 
            edgeMap.put(e, e); 
        } 
        return new IsomorphicGraphMapping<>(vertexMap, edgeMap); 
    } catch (RuntimeException ex) { 
        throw new IllegalStateException("Failed to create identity mapping", ex); 
    } 
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    if (graph == null) {
        throw new NullPointerException("graph");
    }
    Map<V,V> vertexMap = new HashMap<>();
    for (V v : graph.vertexSet()) {
        vertexMap.put(v, v);
    }
    return new IsomorphicGraphMapping<>(graph, graph, vertexMap);
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    if (graph == null) {
        throw new IllegalArgumentException("graph must not be null");
    }
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<>();
    for (V vertex : graph.getVertices()) {
        mapping.mapVertex(vertex, vertex);
    }
    for (E edge : graph.getEdges()) {
        mapping.mapEdge(edge, edge);
    }
    return mapping;
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    if (graph == null) {
        throw new IllegalArgumentException("graph must not be null");
    }
    // Create a mapping from the graph to itself
    final IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<>(graph, graph);
    // Map each vertex to itself
    for (V v : graph.vertexSet()) {
        mapping.mapVertex(v, v);
    }
    // Map each edge to itself (optional but explicit)
    for (E e : graph.edgeSet()) {
        mapping.mapEdge(e, e);
    }
    return mapping;
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children == null && file.exists()) {
            throw new IOException("Unable to list contents of directory: " + file);
        }
        if (children != null) {
            for (File child : children) {
                forceDeleteOnExit(child);
            }
        }
    }
    file.deleteOnExit();
}

