@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap) {
    try {
        // Define sizes of the two partitions of the bipartite graph
        int leftSize = 3;
        int rightSize = 3;
        // Create left partition vertices and add them to the target graph
        for (int i = 1; i <= leftSize; i++) {
            String label = "u" + i;
            @SuppressWarnings("unchecked")
            V vertex = (V) (Object) label;
            target.addVertex(vertex);
            resultMap.put(label, vertex);
        }
        // Create right partition vertices and add them to the target graph
        for (int j = 1; j <= rightSize; j++) {
            String label = "v" + j;
            @SuppressWarnings("unchecked")
            V vertex = (V) (Object) label;
            target.addVertex(vertex);
            resultMap.put(label, vertex);
        }
        // Add edges between every pair of vertices from different partitions
        for (int i = 1; i <= leftSize; i++) {
            @SuppressWarnings("unchecked")
            V leftVertex = (V) (Object) ("u" + i);
            for (int j = 1; j <= rightSize; j++) {
                @SuppressWarnings("unchecked")
                V rightVertex = (V) (Object) ("v" + j);
                target.addEdge(leftVertex, rightVertex);
            }
        }
    } catch (Exception e) {
        // Log or rethrow as a runtime exception if graph operations fail
        throw new RuntimeException("Failed to generate complete bipartite graph", e);
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    try {
        int leftSize = 2;
        int rightSize = 2;
        java.util.ArrayList<V> leftVertices = new java.util.ArrayList<>();
        java.util.ArrayList<V> rightVertices = new java.util.ArrayList<>();

        for (int i = 0; i < leftSize; i++) {
            V v = target.addVertex();
            leftVertices.add(v);
            resultMap.put("L" + i, v);
        }
        for (int i = 0; i < rightSize; i++) {
            V v = target.addVertex();
            rightVertices.add(v);
            resultMap.put("R" + i, v);
        }

        for (V lv : leftVertices) {
            for (V rv : rightVertices) {
                target.addEdge(lv, rv);
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to generate complete bipartite graph", e);
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Graph target and resultMap must not be null");
    }
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String key = entry.getKey();
        V vertex = entry.getValue();
        if (key == null || vertex == null) continue;
        if (key.startsWith("U") || key.startsWith("u")) {
            left.add(vertex);
        } else if (key.startsWith("V") || key.startsWith("v")) {
            right.add(vertex);
        }
    }
    for (V u : left) {
        for (V v : right) {
            target.addEdge(u, v);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){  
    List<V> left = new ArrayList<>();  
    List<V> right = new ArrayList<>();  
    for (Map.Entry<String,V> entry : resultMap.entrySet()){  
        String key = entry.getKey();  
        V v = entry.getValue();  
        if (key != null && key.startsWith("L")){  
            left.add(v);  
        }else if (key != null && key.startsWith("R")){  
            right.add(v);  
        }else{  
            // If no clear partition prefix, distribute alternately  
            if (left.size() <= right.size()){  
                left.add(v);  
            }else{  
                right.add(v);  
            }  
        }  
    }  
    // Add all vertices to the target graph  
    for (V v : left){  
        target.addVertex(v);  
    }  
    for (V v : right){  
        target.addVertex(v);  
    }  
    // Create edges between every pair of left and right vertices  
    for (V u : left){  
        for (V v : right){  
            if (target.getEdge(u, v) == null){  
                target.addEdge(u, v);  
            }  
        }  
    }  
}

