public long readLong(final int offset){
    if (offset < 0 || offset + 8 > this.data.length) {
        throw new IllegalArgumentException("Invalid offset: " + offset);
    }
    return ((long)(this.data[offset] & 0xFF) << 56)
        | ((long)(this.data[offset + 1] & 0xFF) << 48)
        | ((long)(this.data[offset + 2] & 0xFF) << 40)
        | ((long)(this.data[offset + 3] & 0xFF) << 32)
        | ((long)(this.data[offset + 4] & 0xFF) << 24)
        | ((long)(this.data[offset + 5] & 0xFF) << 16)
        | ((long)(this.data[offset + 6] & 0xFF) << 8)
        | ((long)(this.data[offset + 7] & 0xFF));
}

public long readLong(final int offset){
    if (offset < 0 || offset + 7 >= this.bytes.length) {
        throw new ArrayIndexOutOfBoundsException("Offset out of bounds");
    }
    final int high = ((this.bytes[offset] & 0xFF) << 24) |
                     ((this.bytes[offset + 1] & 0xFF) << 16) |
                     ((this.bytes[offset + 2] & 0xFF) << 8) |
                     (this.bytes[offset + 3] & 0xFF);
    final int low = ((this.bytes[offset + 4] & 0xFF) << 24) |
                    ((this.bytes[offset + 5] & 0xFF) << 16) |
                    ((this.bytes[offset + 6] & 0xFF) << 8) |
                    (this.bytes[offset + 7] & 0xFF);
    return ((long) high << 32) | (low & 0xffffffffL);
}

