protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long current = start;
    try {
        while (current < end) {
            long next = Math.min(current + FETCH_DATA_DURATION, end);
            ranges.add(new TimeRange(current, next));
            current = next;
        }
    } catch (Exception e) {
        // safest fallback: clear any partially created ranges
        ranges.clear();
        throw new IllegalStateException("Failed to build time ranges", e);
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    // Ensure FETCH_DATA_DURATION is positive
    if (FETCH_DATA_DURATION <= 0) {
        ranges.add(new TimeRange(start, end));
        return ranges;
    }
    long low = Math.min(start, end);
    long high = Math.max(start, end);
    if (low == high) {
        ranges.add(new TimeRange(low, high));
        return ranges;
    }
    for (long s = low; s < high; s += FETCH_DATA_DURATION) {
        long e = Math.min(s + FETCH_DATA_DURATION, high);
        ranges.add(new TimeRange(s, e));
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<TimeRange>();
    try {
        // Sanity checks
        if (start >= end || FETCH_DATA_DURATION <= 0) {
            return ranges;
        }
        long current = start;
        while (current < end) {
            long next;
            if (FETCH_DATA_DURATION > 0 && current > Long.MAX_VALUE - FETCH_DATA_DURATION) {
                next = end;
            } else {
                next = current + FETCH_DATA_DURATION;
                if (next > end) {
                    next = end;
                }
            }
            ranges.add(new TimeRange(current, next));
            current = next;
            if (current == end) {
                break;
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to build time ranges", e);
    }
    return ranges;
}

protected List<TimeRange> function ( long arg0 , long arg1 ) {
