static long compressTimeBucket(long timeBucket,int dayStep){
    if(timeBucket <= 0 || dayStep <= 0){
        throw new IllegalArgumentException(("timeBucket and dayStep must be positive, received " + timeBucket + " and " + dayStep));
    }
    long yearMonth = timeBucket / 100;
    int day = (int)(timeBucket % 100);
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    return yearMonth * 100 + newDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    try{
        int year = (int)(timeBucket / 10000);
        int month = (int)((timeBucket % 10000) / 100);
        int day = (int)(timeBucket % 100);
        java.time.LocalDate date = java.time.LocalDate.of(year, month, day);
        long epochDay = date.toEpochDay();
        long bucketEpochDay = (epochDay / dayStep) * dayStep;
        java.time.LocalDate bucketDate = java.time.LocalDate.ofEpochDay(bucketEpochDay);
        return bucketDate.getYear() * 10000 + bucketDate.getMonthValue() * 100 + bucketDate.getDayOfMonth();
    }catch(Exception e){
        throw new IllegalArgumentException("Invalid timeBucket value: " + timeBucket, e);
    }
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket <= 0 || dayStep <= 0) {
        return timeBucket;
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    if (month < 1 || month > 12) {
        return timeBucket;
    }

    java.time.YearMonth ym;
    try {
        ym = java.time.YearMonth.of(year, month);
    } catch (Exception e) {
        return timeBucket;
    }
    int daysInMonth = ym.lengthOfMonth();

    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    if (newDay > daysInMonth) {
        newDay = daysInMonth;
    }
    if (newDay < 1) {
        newDay = 1;
    }

    return year * 10000L + month * 100L + newDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be greater than zero");
    }
    int year  = (int)(timeBucket / 10000L);
    int month = (int)((timeBucket / 100L) % 100L);
    int day   = (int)(timeBucket % 100L);
    if(month < 1 || month > 12 || day < 1 || day > 31){
        throw new IllegalArgumentException("Invalid timeBucket value");
    }
    int groupIdx = (day - 1) / dayStep;
    int compressedDay = groupIdx * dayStep + 1;
    return year * 10000L + month * 100L + compressedDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        return 0;
    }
    int strLen = str.length();
    if (index < 0 || len < 0 || index > strLen || index + len > strLen) {
        throw new IllegalArgumentException("Index or length out of bounds");
    }
    if (len == 0) {
        return 0;
    }
    int byteCount = 0;
    int i = 0;
    while (i < len) {
        char ch1 = str.charAt(index + i);
        int codePoint;
        if (Character.isHighSurrogate(ch1) && (i + 1) < len) {
            char ch2 = str.charAt(index + i + 1);
            if (Character.isLowSurrogate(ch2)) {
                codePoint = Character.toCodePoint(ch1, ch2);
                i++; // consume low surrogate
            } else {
                codePoint = ch1;
            }
        } else {
            codePoint = ch1;
        }
        if (codePoint <= 0x7F) {
            byteCount += 1;
        } else if (codePoint <= 0x7FF) {
            byteCount += 2;
        } else if (codePoint <= 0xFFFF) {
            byteCount += 3;
        } else {
            byteCount += 4;
        }
        i++;
    }
    return byteCount;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null) {
