    }
    int strLen = str.length();
    if (index < 0 || len < 0 || index + len > strLen) {
        throw new IndexOutOfBoundsException("index or len out of bounds");
    }
    int end = index + len;
    int size = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                // encode surrogate pair as four bytes
                size += 4;
                i++; // skip low surrogate
            } else {
                // malformed surrogate, use replacement character U+FFFD (3 bytes)
                size += 3;
            }
        } else {
            size += 3;
        }
    }
    return size;
}

