    if (u == null) {
        throw new IllegalArgumentException("URI must not be null");
    }
    String path = u.getPath();
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // If path is absolute, ignore leading '/'
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return segments;
    }
    String[] parts = path.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue; // skip empty segments that may arise from consecutive slashes
        }
        String decodedPart = part;
        if (decode) {
            try {
                decodedPart = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException ex) {
                throw new RuntimeException(ex);
            }
        }
        segments.add(new PathSegmentImpl(decodedPart));
    }
    return segments;
}

