private void pop(final String descriptor){
    if(descriptor == null || descriptor.isEmpty()){
        return;
    }
    int count = 0;
    int posIndex = 0;
    if(descriptor.charAt(0) == '('){
        int end = descriptor.indexOf(')');
        if(end == -1){
            return; // malformed descriptor
        }
        while(posIndex < end){
            char c = descriptor.charAt(posIndex);
            if(c == '['){
                // skip all '['
                while(posIndex < end && descriptor.charAt(posIndex) == '[') posIndex++;
                // component type
                posIndex++;
                count++;
            }else if(c == 'L'){
                int semicolon = descriptor.indexOf(';', posIndex+1);
                if(semicolon == -1){
                    return; // malformed descriptor
                }
                posIndex = semicolon + 1;
                count++;
            }else{
                // primitive type
                posIndex++;
                count++;
            }
        }
        // return type after ')' is ignored for popping
    }else{
        // Single type descriptor
        while(posIndex < descriptor.length()){
            char c = descriptor.charAt(posIndex);
            if(c == '['){
                while(posIndex < descriptor.length() && descriptor.charAt(posIndex) == '[') posIndex++;
                posIndex++;
                count++;
            }else if(c == 'L'){
                int semicolon = descriptor.indexOf(';', posIndex+1);
                if(semicolon == -1){
                    return; // malformed descriptor
                }
                posIndex = semicolon + 1;
                count++;
            }else{
                posIndex++;
                count++;
            }
        }
    }
    // Pop the stack the required number of slots
    for (int i = 0; i < count; i++) {
        if (pos <= 0) {
            break; // nothing left to pop
        }
        stack[--pos] = null;
    }
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    int pos = 0;
    // If descriptor is a type descriptor, pop one type
    if (descriptor.charAt(0) != '('){
        outputFrameStack.pop();
        return;
    }
    // Method descriptor: skip '('
    pos = 1;
    while (pos < descriptor.length() && descriptor.charAt(pos) != ')'){
        // Skip array dimension delimiters
        while (descriptor.charAt(pos) == '['){
            pos++;
        }
        char c = descriptor.charAt(pos);
        if (c == 'L'){
            int semicolon = descriptor.indexOf(';', pos);
            if (semicolon < 0){
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            pos = semicolon + 1;
        } else {
            pos++;
        }
        // pop one abstract type for each argument
        outputFrameStack.pop();
    }
}

