public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null || node == null) {
        return 0;
    }
    int totalSize = 0;
    LinkedBuffer curr = node;
    while (curr != null) {
        // Assume LinkedBuffer has fields: byte[] buf, int pos, int limit, LinkedBuffer next
        int bytesToWrite = curr.limit - curr.pos;
        if (bytesToWrite > 0) {
            out.write(curr.buf, curr.pos, bytesToWrite);
            totalSize += bytesToWrite;
        }
        curr = curr.next;
    }
    return totalSize;
}

