}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new NullPointerException("DataOutput must not be null");
    }
    int total = 0;
    LinkedBuffer cur = node;
    while (cur != null) {
        int readPos = cur.readPos;
        int len = cur.buf.length - readPos;
        if (len > 0) {
            out.write(cur.buf, readPos, len);
            total += len;
        }
        cur = cur.next;
    }
    return total;
}

