@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type != Character.class && type != char.class) {
        throw new Exception("Target type must be java.lang.Character");
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.isEmpty()) {
            throw new Exception("Cannot convert empty string to Character");
        }
        return str.charAt(0);
    }
    if (value instanceof Number) {
        return (char) ((Number) value).intValue();
    }
    if (value instanceof byte[]) {
        byte[] arr = (byte[]) value;
        if (arr.length == 0) {
            throw new Exception("Cannot convert empty byte array to Character");
        }
        return (char) arr[0];
    }
    String str = value.toString();
    if (str.isEmpty()) {
        throw new Exception("Cannot convert value to Character");
    }
    return str.charAt(0);
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    if (type != null && !type.isAssignableFrom(Character.class)) {
        throw new Exception("Target type is not Character: " + type);
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < Character.MIN_VALUE || intVal > Character.MAX_VALUE) {
            throw new Exception("Number value out of range for Character: " + intVal);
        }
        return (char) intVal;
    }
    String str = value.toString();
    if (str.length() != 1) {
        throw new Exception("Cannot convert String to Character: \"" + str + "\"");
    }
    return str.charAt(0);
}

