    int limit = start;
    if (desiredCapacity >= 1000) {
        long llimit = (long) desiredCapacity * 111 / 100 + 1; // 11% more, integer arithmetic
        if (llimit > Integer.MAX_VALUE) llimit = Integer.MAX_VALUE;
        limit = (int) llimit;
    }
    for (int n = start; n <= limit; n++) {
        if (isPrime(n)) {
            return n;
        }
    }
    throw new IllegalArgumentException("No prime found within 11% of desiredCapacity");
}

