private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new HashMap<>();
    if (jsonObject == null) {
        return content;
    }
    try {
        for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
            String key = entry.getKey();
            JsonElement element = entry.getValue();
            if (element == null || element.isJsonNull()) {
                content.put(key, null);
            } else if (element.isJsonPrimitive()) {
                JsonPrimitive prim = element.getAsJsonPrimitive();
                if (prim.isBoolean()) {
                    content.put(key, prim.getAsBoolean());
                } else if (prim.isNumber()) {
                    content.put(key, prim.getAsNumber());
                } else if (prim.isString()) {
                    content.put(key, prim.getAsString());
                }
            } else if (element.isJsonObject()) {
                content.put(key, buildContent(element.getAsJsonObject()));
            } else if (element.isJsonArray()) {
                List<Object> arrayList = new ArrayList<>();
                for (JsonElement arrElem : element.getAsJsonArray()) {
                    if (arrElem.isJsonPrimitive()) {
                        JsonPrimitive prim = arrElem.getAsJsonPrimitive();
                        if (prim.isBoolean()) {
                            arrayList.add(prim.getAsBoolean());
                        } else if (prim.isNumber()) {
                            arrayList.add(prim.getAsNumber());
                        } else if (prim.isString()) {
                            arrayList.add(prim.getAsString());
                        }
                    } else if (arrElem.isJsonObject()) {
                        arrayList.add(buildContent(arrElem.getAsJsonObject()));
                    } else if (arrElem.isJsonArray()) {
                        // Nested arrays are converted to a list of primitives/objects.
                        arrayList.add(buildContent(coerceJsonObjectFromArray(arrElem.getAsJsonArray())));
