            javax.json.JsonValue value = entry.getValue();
            Object javaValue = null;
            switch (value.getValueType()) {
                case STRING:
                    javaValue = ((javax.json.JsonString) value).getString();
                    break;
                case NUMBER:
                    javax.json.JsonNumber num = (javax.json.JsonNumber) value;
                    javaValue = num.isIntegral() ? num.longValue() : num.doubleValue();
                    break;
                case TRUE:
                    javaValue = Boolean.TRUE;
                    break;
                case FALSE:
                    javaValue = Boolean.FALSE;
                    break;
                case NULL:
                    javaValue = null;
                    break;
                case OBJECT:
                    javaValue = this.buildContent((javax.json.JsonObject) value);
                    break;
                case ARRAY:
                    javax.json.JsonArray arr = (javax.json.JsonArray) value;
                    java.util.List<Object> list = new java.util.ArrayList<>();
                    for (javax.json.JsonValue av : arr) {
                        Object elem = null;
                        switch (av.getValueType()) {
                            case STRING:
                                elem = ((javax.json.JsonString) av).getString();
                                break;
                            case NUMBER:
                                javax.json.JsonNumber n = (javax.json.JsonNumber) av;
                                elem = n.isIntegral() ? n.longValue() : n.doubleValue();
                                break;
                            case TRUE:
                                elem = Boolean.TRUE;
                                break;
                            case FALSE:
                                elem = Boolean.FALSE;
                                break;
                            case NULL:
                                elem = null;
                                break;
                            case OBJECT:
                                elem = this.buildContent((javax.json.JsonObject) av);
                                break;
                            case ARRAY:
                                // nested arrays are converted lazily
                                elem = this.buildContent((javax.json.JsonObject) av);
                                break;
                            default:
                                elem = null;
                        }
                        list.add(elem);
                    }
                    javaValue = list;
                    break;
                default:
                    javaValue = null;
            }
            content.put(key, javaValue);
        }
    } catch (Exception e) {
        // In case of any unexpected exception, return the content built so far
    }
    return content;
