    try {
        // Assume a root node exists in the containing class
        if (root == null) {
            return 0;
        }
        java.util.Queue<Category> queue = new java.util.LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            Category current = queue.poll();
            if (current == null) {
                continue;
            }
            java.util.List<Category> children = current.getChildren();
            if (children == null) {
                continue;
            }
            java.util.Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                if (child == null) {
                    continue;
                }
                if (!child.isActive()) {
                    it.remove();            // Removes the inactive node from the tree
                    removedCount++;
                } else {
                    queue.offer(child);      // Process active child nodes
                }
            }
        }
    } catch (Exception e) {
        // In a real application you might log this exception
        throw new RuntimeException("Error while removing unused category nodes", e);
    }
    return removedCount;
}

