    int offset = constantPoolEntryIndex;
    if (offset < 0 || offset + 2 > classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index");
    }
    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    if (charBuffer == null || charBuffer.length < length) {
        throw new IllegalArgumentException("Provided char buffer is insufficient");
    }
    for (int i = 0; i < length; ++i) {
        charBuffer[i] = (char) (classFileBuffer[offset + 2 + i] & 0xFF);
    }
    return new String(charBuffer, 0, length);
}

