        if (charBuffer.length < len) {
            throw new IllegalArgumentException("charBuffer too small for UTF-8 string");
        }
        int bytePos = entryOffset + 3;
        java.nio.ByteBuffer bb = java.nio.ByteBuffer.wrap(classFileBuffer, bytePos, len);
        java.nio.charset.CharsetDecoder decoder = java.nio.charset.StandardCharsets.UTF_8.newDecoder();
