private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new NullPointerException("predicate");
    }
    if (start == null || stop == null) {
        throw new NullPointerException("start or stop");
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node current = start;
    while (true) {
        if (predicate.test(current)) {
            return circ;
        }
        if (current == stop) {
            return circ;
        }
        // Advance circulator in the requested direction
        circ.move(dir);
        current = circ.getNode();
        // Prevent an infinite loop in case of a malformed circulator
        if (current == start) {
            return circ;
        }
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // If we start at the stop node, return immediately
    if (circ.node().equals(stop)) {
        return circ;
    }
    boolean firstIteration = true;
    while (true) {
        Node current = circ.node();
        if (predicate.test(current)) {
            break;
        }
        circ.next();
        // If we reached the stop node, stop searching
        if (circ.node().equals(stop)) {
            break;
        }
        // Prevent infinite loops on a closed circulator
        if (!firstIteration && circ.node().equals(start)) {
            break;
        }
        firstIteration = false;
    }
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null.");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null.");
    }

    // Create a circulator beginning at the start node. It is assumed that the
    // OuterFaceCirculator constructor accepts a starting node and a direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // Handle the trivial case where start is already the stop node.
    if (start == stop) {
        return circ;
    }

    Node current = circ.getNode();  // The current node pointed to by the circulator.
    while (!current.equals(stop) && !predicate.test(current)) {
        try {
            circ.next();                 // Advance to the next node along the outer face.
            current = circ.getNode();    // Update the reference to the new node.
        } catch (IndexOutOfBoundsException | IllegalStateException e) {
            // In case the circulator becomes invalid (e.g., closed loop without stop),
            // return a circulator pointing to the stop node to fulfill the contract.
            // We construct a new circulator starting at the stop node.
            return new OuterFaceCirculator(stop, dir);
        }
    }

    // At this point either `current` satisfies the predicate or it is the stop node.
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop nodes must not be null");
    }

    // Create a circulator that starts at the provided start node and traverses towards stop
    OuterFaceCirculator circ = new OuterFaceCirculator(start, stop, dir);

    // Iterate over the nodes on the outer face until we either find a node that satisfies the predicate
    // or reach the stop node.
    for (Node current = start; !current.equals(stop); ) {
        if (predicate.test(current)) {
            // Return a new circulator positioned at the matching node
            return new OuterFaceCirculator(current, stop, dir);
        }
        // Advance to the next node along the outer face.
        current = circ.next(); // Assume circ.next() moves along the direction and returns the next Node.
    }

    // If no node satisfied the predicate, return a circulator that points to the stop node.
    return new OuterFaceCirculator(stop, stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }
    try {
        OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
        Node current = start;
        // Loop until we hit the stop node or find a satisfying node
        while (current != null && !current.equals(stop)) {
            if (predicate.test(current)) {
                return circ;
            }
            circ.next(); // advance circulator
            current = circ.get(); // retrieve the node currently pointed to
        }
        // either reached stop node or went beyond; return circulator pointing at stop
        return circ;
    } catch (Exception e) {
        throw new RuntimeException("Failed to traverse outer face", e);
    }
}

