        } else {
            if (nonAsciiSet == null) {
                nonAsciiSet = new java.util.HashSet<>();
            }
            nonAsciiSet.add(ch);
        }
    }

    StringBuilder sb = new StringBuilder(inString.length());
    for (int i = 0; i < inString.length(); i++) {
        char ch = inString.charAt(i);
        boolean delete = false;
        if (ch < asciiFlags.length) {
            delete = asciiFlags[ch];
        } else if (nonAsciiSet != null) {
            delete = nonAsciiSet.contains(ch);
        }
        if (!delete) {
