static void register(Object value) {
    if (value == null) return;
    // Registration logic: add to a static registry to avoid infinite loops during reflection
    try {
        java.util.Set<Object> registry = java.util.Collections.synchronizedSet(new java.util.HashSet<Object>());
        if (!registry.contains(value)) {
            registry.add(value);
        }
    } catch (Throwable t) {
        // Ignore any errors to prevent recursion issues
    }
}

