protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if(tour == null || tour.isEmpty() || graph == null){
        return null;
    }
    try{
        // Map each vertex to its incident edges
        Map<V,Set<E>> adjacency = new HashMap<>();
        for(E e : tour){
            V source = graph.getEdgeSource(e);
            V target = graph.getEdgeTarget(e);
            adjacency.computeIfAbsent(source, k -> new HashSet<>()).add(e);
            adjacency.computeIfAbsent(target, k -> new HashSet<>()).add(e);
        }

        List<V> vertexList = new ArrayList<>();
        List<E> edgeList = new ArrayList<>();
        Set<E> remaining = new HashSet<>(tour);

        // Start from an arbitrary edge
        E startEdge = remaining.iterator().next();
        V startSource = graph.getEdgeSource(startEdge);
        V startTarget = graph.getEdgeTarget(startEdge);

        vertexList.add(startSource);
        edgeList.add(startEdge);
        vertexList.add(startTarget);
        remaining.remove(startEdge);

        V current = startTarget;
        while(!remaining.isEmpty()){
            boolean found = false;
            for(E e : new HashSet<>(remaining)){
                V s = graph.getEdgeSource(e);
                V t = graph.getEdgeTarget(e);
                if(s.equals(current)){
                    vertexList.add(t);
                    edgeList.add(e);
                    remaining.remove(e);
                    current = t;
                    found = true;
                    break;
                } else if(t.equals(current)){
                    // In case of undirected graph allow reverse direction
                    vertexList.add(s);
                    edgeList.add(e);
                    remaining.remove(e);
                    current = s;
                    found = true;
                    break;
                }
            }
            if(!found){
                // No connecting edge found, abort
                break;
            }
        }

        if(edgeList.isEmpty()){
            return null;
        }

        // Construct and return a GraphPath using GraphWalk implementation
        return new org.jgrapht.graph.GraphWalk<>(graph, vertexList, edgeList, true);
    }catch(Exception ex){
        // In case of any runtime issue return null
        return null;
    }
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        // Return an empty path (start and end are the same with no edges)
        List<V> vertices = new ArrayList<>();
        List<E> edges = new ArrayList<>();
        return new CoreGraphPath<>(graph, null, null, 0.0, 0.0, edges, vertices);
    }
    // Build adjacency map for quick lookup
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        // For undirected graphs we also need the reverse relation
        if (!graph.getType().isDirected()) {
            adjacency.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
        }
    }

    // Start from any edge's source vertex
    Iterator<E> it = tour.iterator();
    E firstEdge = it.next();
    V startVertex = graph.getEdgeSource(firstEdge);
    V currentVertex = startVertex;

    List<E> edgeList = new ArrayList<>();
    List<V> vertexList = new ArrayList<>();
    vertexList.add(currentVertex);

    Set<E> remaining = new HashSet<>(tour);

    double totalWeight = 0.0;
    double totalLength = 0.0;

    while (!remaining.isEmpty()) {
        List<E> candidates = adjacency.get(currentVertex);
        if (candidates == null) {
            throw new IllegalArgumentException("Graph is not a tour: missing connections");
        }
        E nextEdge = null;
        for (E e : candidates) {
            if (remaining.contains(e)) {
                // Check direction if graph is directed
                if (graph.getType().isDirected()) {
                    if (graph.getEdgeSource(e).equals(currentVertex)) {
                        nextEdge = e;
                        break;
                    }
                } else {
                    nextEdge = e;
                    break;
                }
            }
        }
        if (nextEdge == null) {
            throw new IllegalArgumentException("Cannot find a continuation edge from vertex: " + currentVertex);
        }
        remaining.remove(nextEdge);
        edgeList.add(nextEdge);

        V nextVertex;
        if (graph.getType().isDirected()) {
            nextVertex = graph.getEdgeTarget(nextEdge);
        } else {
            // Undirected: choose the other endpoint
            V src = graph.getEdgeSource(nextEdge);
            V tgt = graph.getEdgeTarget(nextEdge);
            nextVertex = src.equals(currentVertex) ? tgt : src;
        }
        vertexList.add(nextVertex);

        // Accumulate weight and length if available
        double w = graph.getEdgeWeight(nextEdge);
        totalWeight += w;
        totalLength += w; // Assuming length equals weight; adjust if graph has separate length

        currentVertex = nextVertex;

        // Detect cycle completion
        if (remaining.isEmpty() && currentVertex.equals(startVertex)) {
            break;
        }
    }

    return new CoreGraphPath<>(graph, vertexList.get(0), currentVertex, totalLength, totalWeight, edgeList, vertexList);
}

