    if (bounds == null){
        throw new IllegalArgumentException("bounds cannot be null");
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++){
        suffix.add(0);
    }
    long total = 0L;
    for (int val : bounds){
        total += val;
    }
    long running = 0L;
    for (int i = n - 1; i >= 0; i--){
        running += bounds.get(i);
        suffix.set(i, (int) running);
    }
    return new Pair<>(suffix, total);
}

