    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (from < 0 || to >= arr.length) {
        throw new IndexOutOfBoundsException("Indices out of bounds");
    }
    if (from > to) {
        throw new IllegalArgumentException("From index cannot be greater than to index");
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array reference is null");
    }
    if (from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid from/to indices");
    }
    int left = from;
    int right = to;
    while (left < right) {
        V temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list == this) {
        return;
    }
    Object firstLock, secondLock;
    if (System.identityHashCode(this) < System.identityHashCode(list)) {
        firstLock = this;
        secondLock = list;
    } else {
        firstLock = list;
        secondLock = this;
    }
    synchronized (firstLock) {
        synchronized (secondLock) {
            ListNode<E> srcHead = list.head;
            if (srcHead == null) {
                return;
            }
            ListNode<E> srcTail = list.tail;
            int movedSize = list.size;
            list.head = null;
            list.tail = null;
            list.size = 0;
            if (this.head == null) {
                this.head = srcHead;
                this.tail = srcTail;
            } else {
                this.tail.next = srcHead;
                srcHead.prev = this.tail;
                this.tail = srcTail;
            }
            this.size += movedSize;
        }
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null){
        throw new IllegalArgumentException("list cannot be null");
    }
    try {
        int count = list.size();
        for (int i = 0; i < count; i++) {
            // Assume the list exposes a method to get its first node
            ListNodeImpl node = list.getFirstNode();
            if (node == null) {
                break; // nothing left to move
            }
            // Remove the node from the source list
            list.removeListNode(node);
            // Add the node to this list
            addListNode(node);
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to atomically move all list nodes", e);
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list == this) {
        return;
    }
    try {
        // Iterate over each node in the source list
        ListNode<E> current = list.head;
        while (current != null) {
            ListNode<E> next = current.next; // keep reference to next node
            // Remove the node from the source list
            removeListNode(current);
            // Add the node to this list
            addListNode(current);
            current = next;
        }
        // After all nodes are moved, reset the source list to empty
        list.head = null;
        list.tail = null;
        list.size = 0;
    } catch (Exception e) {
        throw new RuntimeException("Failed to move list nodes", e);
    }
}

