    }
    try{
        for (Object key : map.keySet()){
            if (!(key instanceof String)){
                continue; // skip non‑string keys
            }
            String prop = (String) key;
            // source must be both readable and writable
            if (!map.isReadable(prop) || !map.isWritable(prop)){
                continue;
            }
            Object value = map.get(prop);
            // only write if target property is writable
            if (!this.isWritable(prop)){
                continue;
            }
            try{
                this.set(prop, value);
            }catch(RuntimeException e){
                // ignore inability to set this particular property
            }
        }
    }catch(Exception ex){
        throw new RuntimeException("Failed to copy writable properties", ex);
    }
