    }
    // Convert the set to a list for indexed access
    List<V> list = new ArrayList<>(vertices);
    int n = list.size();
    for (int i = 0; i < n; i++) {
        V v1 = list.get(i);
        for (int j = i + 1; j < n; j++) {
            V v2 = list.get(j);
            try {
                if (graph.getEdge(v1, v2) == null) {
