                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    // A set with 0 or 1 vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2)) {
                // For undirected graphs, getEdge(v1, v2) should return non-null if an edge exists
                if (graph.getEdge(v1, v2) == null) {
                    return false;
                }
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        // For each key, the maximum lower bound is the index of the previous key
        // (or 0 for the first key if no lower bound exists).
        lowerBounds.add(i > 0 ? i - 1 : 0);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    int n = keys.size();
    List<Integer> lowerBounds = new ArrayList<>(n);
    if (n == 0) {
        return lowerBounds;
    }
    // Create a sorted copy of the keys
    List<K> sorted = new ArrayList<>(keys);
    try {
        Collections.sort(sorted, Comparator.naturalOrder());
    } catch (ClassCastException e) {
        // Keys are not comparable
        throw new IllegalArgumentException("Key type does not implement Comparable", e);
    }
    for (K key : keys) {
        if (key == null) {
            lowerBounds.add(null);
            continue;
        }
        int pos = Collections.binarySearch(sorted, key);
        int lowerIdx;
        if (pos >= 0) {
            lowerIdx = pos - 1;
        } else {
            int insertionPoint = -pos - 1;
            lowerIdx = insertionPoint - 1;
        }
        if (lowerIdx >= 0) {
            K lowerKey = sorted.get(lowerIdx);
            if (lowerKey instanceof Integer) {
                lowerBounds.add((Integer) lowerKey);
            } else {
                // If K is not Integer, attempt to convert via toString
                try {
                    lowerBounds.add(Integer.valueOf(lowerKey.toString()));
                } catch (NumberFormatException ex) {
                    lowerBounds.add(null);
                }
            }
        } else {
            lowerBounds.add(null); // No lower bound
        }
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return bounds;
    }
    try {
        for (K key : keys) {
            if (key == null) {
                bounds.add(-1);
                continue;
            }
            int index = Collections.binarySearch(keys, key);
            if (index >= 0) {
                bounds.add(index);
            } else {
                int insertionPoint = -index - 1;
                int floorIndex = insertionPoint - 1;
                bounds.add(floorIndex >= 0 ? floorIndex : -1);
            }
        }
    } catch (ClassCastException e) {
        // If elements cannot be compared, return -1 for each key
        bounds.clear();
        for (int i = 0; i < keys.size(); i++) {
            bounds.add(-1);
        }
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) 
        return bounds;
    // Create a copy and sort it using natural ordering
    List<K> sorted = new ArrayList<>(keys);
    try {
        Collections.sort(sorted);
    } catch (ClassCastException e) {
        // Elements are not comparable; cannot compute bounds
        return bounds;
    }
    // For each key, find the maximum lower bound (predecessor in the sorted list)
    for (int i = 0; i < sorted.size(); i++) {
        if (i == 0) {
            bounds.add(null); // no lower bound for the smallest element
        } else {
            K lowerKey = sorted.get(i - 1);
            // Attempt to convert the lower key to Integer
            Integer lowerValue = null;
            try {
                lowerValue = (Integer) lowerKey;
            } catch (ClassCastException | NullPointerException e) {
                try {
                    lowerValue = Integer.parseInt(lowerKey.toString());
                } catch (NumberFormatException | NullPointerException nf) {
                    lowerValue = null; // fallback if conversion fails
                }
            }
            bounds.add(lowerValue);
        }
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> result = new ArrayList<>(keys != null ? keys.size() : 0);
    if (keys == null || keys.isEmpty()) {
        return result;
    }

    // Convert keys to integer values if possible
    List<Integer> intKeys = new ArrayList<>(keys.size());
    for (K key : keys) {
        if (key instanceof Integer) {
            intKeys.add((Integer) key);
        } else if (key instanceof Number) {
            intKeys.add(((Number) key).intValue());
        } else {
            throw new IllegalArgumentException("Key of type " + (key == null ? "null" : key.getClass().getName()) + " cannot be converted to an integer");
        }
    }

    // Compute maximum lower bound for each key
    for (int i = 0; i < intKeys.size(); i++) {
        int current = intKeys.get(i);
        int maxLower = Integer.MIN_VALUE;
        for (int j = 0; j < intKeys.size(); j++) {
            if (i == j) {
                continue;
            }
            int candidate = intKeys.get(j);
            if (candidate < current && candidate > maxLower) {
                maxLower = candidate;
            }
        }
        // If no lower bound was found, use null or a sentinel; here we use 0
        result.add(maxLower == Integer.MIN_VALUE ? 0 : maxLower);
    }

    return result;
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int count = 0;
    int i = 0;
    // If descriptor starts with '(' treat it as a method descriptor and skip the argument part
    if (descriptor.charAt(0) == '(') {
        int endArgs = descriptor.indexOf(')');
        if (endArgs == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        i = endArgs + 1;  // Point at the return type (which we ignore)
    }
    // Parse the remaining type descriptors
    while (i < descriptor.length()) {
        char c = descriptor.charAt(i);
        switch (c) {
            case 'B':
            case 'C':
            case 'F':
            case 'I':
            case 'S':
            case 'Z':
                count += 1;
                i += 1;
                break;
            case 'J':
                count += 2;  // long occupies two words
                i += 1;
                break;
            case 'D':
                count += 2;  // double occupies two words
                i += 1;
                break;
            case 'L':  // object type
                int end = descriptor.indexOf(';', i);
                if (end == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
                }
                count += 1;
                i = end + 1;
                break;
            case '[':  // array type
                // Skip all consecutive '[' characters
                while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                    i++;
                }
                // After '['s we must have a type (object or primitive)
                if (i >= descriptor.length()) {
                    throw new IllegalArgumentException("Invalid descriptor: incomplete array type");
                }
                char inner = descriptor.charAt(i);
                if (inner == 'L') {
                    int endObj = descriptor.indexOf(';', i);
                    if (endObj == -1) {
                        throw new IllegalArgumentException("Invalid descriptor: missing ';' for array object type");
                    }
                    i = endObj + 1;
                } else {
                    // primitive type
                    i++;
                }
                count += 1;
                break;
            default:
                throw new IllegalArgumentException("Unknown descriptor type character: " + c);
        }
    }
    // Ensure we do not underflow the stack
    if (pos < count) {
        throw new IllegalStateException("Attempt to pop " + count + " elements from a smaller stack (current pos: " + pos + ")");
    }
    pos -= count;
}

private void pop(final String descriptor){
    if (descriptor == null) return;
    try{
        int len = descriptor.length();
        if (len == 0) return;
        if (descriptor.charAt(0) == '('){
            int end = descriptor.indexOf(')');
            if (end < 0) return;
            int i = 1;
            while (i < end){
                char ch = descriptor.charAt(i);
                // skip array brackets
                while (i < end && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i < end){
                    ch = descriptor.charAt(i);
                }
                if (ch == 'L'){
                    int sem = descriptor.indexOf(';', i);
                    if (sem < 0) return;
                    i = sem + 1;
                }else if (ch == '['){
                    // already handled above
                }else{
                    i++; // primitive type
                }
                // pop one stack slot
                pos--;
            }
        }else{
            // single descriptor
            int i = 0;
            char ch = descriptor.charAt(i);
            while (i < len && descriptor.charAt(i) == '['){
                i++;
            }
            if (i < len){
                ch = descriptor.charAt(i);
                if (ch == 'L'){
                    int sem = descriptor.indexOf(';', i);
                    if (sem < 0) return;
                    i = sem + 1;
                }else{
                    i++; // primitive
                }
            }
            pos--;
        }
    }catch(Exception e){
        // ignore malformed descriptor
    }
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.length() == 0) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }
    int pos = 0;
    int stackPos = this.outputFrameStackPointer; // current top of the output stack
    if (descriptor.charAt(0) == '(') { // method descriptor
        pos = 1; // after '('
        while (pos < descriptor.length() && descriptor.charAt(pos) != ')') {
            // determine the length of the next type descriptor
            int start = pos;
            char c = descriptor.charAt(pos);
            if (c == '[') { // array type
                // consume all '[' characters
                while (descriptor.charAt(pos) == '[') {
                    pos++;
                }
