    if (array == null || array.length == 0) {
        return new String[0];
    }
    int nonNullCount = 0;
    for (Object o : array) {
        if (o != null) {
            nonNullCount++;
        }
    }
    if (nonNullCount == array.length) {
        String[] result = new String[nonNullCount];
        for (int i = 0; i < array.length; i++) {
            result[i] = (String) array[i];
        }
        return result;
    } else {
        String[] result = new String[nonNullCount];
        int idx = 0;
        for (Object o : array) {
            if (o != null) {
                result[idx++] = (String) o;
            }
        }
        return result;
    }
}

