public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        // If expiredThreshold is negative or zero, treat as never expired
        if (expiredThreshold <= 0) {
            return false;
        }
        long currentTime = System.currentTimeMillis();
        // Protect against overflow in addition
        if (timestamp > Long.MAX_VALUE - expiredThreshold) {
            // If the sum would overflow, assume it hasn't expired yet
            return false;
        }
        return currentTime > (timestamp + expiredThreshold);
    } catch (Throwable t) {
        // In case of any unexpected runtime error, consider the metric expired
        return true;
    }
}

