    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            ThreadSnapshot snapshot;
            try {
                // Attempt to parse each line into a ThreadSnapshot instance.
                // Adjust the method name if the actual parsing method differs.
                snapshot = ThreadSnapshot.parseFromString(line);
            } catch (Exception e) {
                // Skip malformed lines.
                continue;
            }
            boolean withinRange = timeRanges == null || timeRanges.isEmpty();
            if (!withinRange) {
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range == null) {
                        continue;
                    }
                    long rangeStart = range.getStartMillis();
                    long rangeEnd = range.getEndMillis();
                    long snapStart = snapshot.getStartTime();
                    long snapEnd = snapshot.getEndTime();
                    if (snapEnd >= rangeStart && snapStart <= rangeEnd) {
                        withinRange = true;
